let packet: [u8; 4] = [200, 100, 150, 120];
let mut sum: u8 = 0;
let mut wraps = 0;

for byte in packet {
    let (next, wrapped) = sum.overflowing_add(byte);
    sum = next;
    if wrapped {
        wraps += 1;
    }
}

